export type AdminAccount = {
  /** The password was generated by another admin: the admin must replace it before using the panel. */
  readonly mustChangePassword: boolean;
};

/** Admins are club members; their password is their member password (`ArcherRepository.passwordHash`). */
export interface AdminRepository {
  /** `null` when this member is not an admin. */
  find(archerLicenceNumber: string): Promise<AdminAccount | null>;
  licenceNumbers(): Promise<string[]>;
  /** Makes the member an admin, or updates their account. */
  save(archerLicenceNumber: string, account: AdminAccount): Promise<void>;
  /** `false` when the member was not an admin. Their panel closes at once: access is checked on every request. */
  remove(archerLicenceNumber: string): Promise<boolean>;
}
